import { flushPromises, mount } from '@vue/test-utils'
import { beforeEach, describe, expect, it, vi } from 'vitest'

import AdminOverviewView from '@/views/admin/AdminOverviewView.vue'
import type { AdminOverview } from '@/types'

const adminApiMock = vi.hoisted(() => ({
  overview: vi.fn(),
}))

vi.mock('@/api/admin', () => ({ adminApi: adminApiMock }))

function overview(overrides: Partial<AdminOverview> = {}): AdminOverview {
  return {
    generated_at: '2026-11-12T06:00:00Z',
    users: { total: 6, active: 5, disabled: 1, admins: 2 },
    conversations: { total: 4, active: 2, archived: 1, deleted: 1 },
    messages: { total: 18 },
    runs: {
      total: 3,
      queued: 0,
      running: 1,
      succeeded: 1,
      failed: 1,
      canceled: 0,
      interrupted: 0,
    },
    a2a_tasks: {
      total: 2,
      submitted: 0,
      working: 1,
      input_required: 0,
      auth_required: 0,
      completed: 1,
      failed: 0,
      canceled: 0,
      rejected: 0,
    },
    knowledge: {
      documents: 5,
      chunks: 20,
      documents_pending: 0,
      documents_indexing: 1,
      documents_ready: 3,
      documents_failed: 1,
    },
    attachments: { total: 2, storage_bytes: 2048, deleted: 1 },
    ...overrides,
  }
}

describe('AdminOverviewView', () => {
  beforeEach(() => {
    vi.clearAllMocks()
    adminApiMock.overview.mockResolvedValue(overview())
  })

  it('渲染关键计数、状态明细与数据时间', async () => {
    const wrapper = mount(AdminOverviewView)
    await flushPromises()

    const text = wrapper.text()
    expect(adminApiMock.overview).toHaveBeenCalledTimes(1)
    expect(text).toContain('管理概览')
    expect(text).toContain('用户')
    expect(text).toContain('6')
    expect(text).toContain('5 活跃 · 2 管理员')
    expect(text).toContain('运行状态')
    expect(text).toContain('等待审批')
    expect(text).toContain('A2A 任务状态')
    expect(text).toContain('知识文档')
    expect(text).toContain('附件存储')
    expect(text).toContain('2026')
    wrapper.unmount()
  })

  it('手动刷新再次请求概览', async () => {
    const wrapper = mount(AdminOverviewView)
    await flushPromises()

    await wrapper.get('button').trigger('click')
    await flushPromises()

    expect(adminApiMock.overview).toHaveBeenCalledTimes(2)
    wrapper.unmount()
  })

  it('加载失败展示错误态并支持重试', async () => {
    adminApiMock.overview.mockRejectedValueOnce(new Error('概览接口不可用'))
    const wrapper = mount(AdminOverviewView)
    await flushPromises()

    expect(wrapper.text()).toContain('概览接口不可用')
    const buttons = wrapper.findAll('button')
    expect(buttons.length).toBeGreaterThan(0)
    await buttons[buttons.length - 1]!.trigger('click')
    await flushPromises()
    expect(adminApiMock.overview).toHaveBeenCalledTimes(2)
    wrapper.unmount()
  })
})

import { computed, ref } from 'vue'
import { defineStore } from 'pinia'

import { authApi } from '@/api/auth'
import type { AuthTokens, RegisterRequest, User } from '@/types'
import { resetDiagnostics } from '@/utils/diagnostics'
import { storage } from '@/utils/storage'

export const useAuthStore = defineStore('auth', () => {
  const user = ref<User | null>(null)
  const accessToken = ref<string | null>(storage.getAccessToken())
  const initialized = ref(false)

  const isAuthenticated = computed(() => Boolean(accessToken.value))
  /** M7：agents/tasks 的写接口仅管理员可用，普通用户不渲染写入口。 */
  const isAdmin = computed(() => user.value?.role === 'admin')

  function setSession(tokens: AuthTokens): void {
    storage.setTokens(tokens)
    accessToken.value = tokens.access_token
  }

  function setUser(next: User | null): void {
    user.value = next
  }

  function clearSession(): void {
    storage.clearTokens()
    accessToken.value = null
    user.value = null
    // 同一浏览器换账号后，诊断缓冲里不能残留上一个账号的 request_id / 错误文案。
    resetDiagnostics()
  }

  async function login(email: string, password: string): Promise<User> {
    const tokens = await authApi.login({ email, password })
    setSession(tokens)
    const profile = await authApi.me()
    setUser(profile)
    initialized.value = true
    return profile
  }

  async function register(body: RegisterRequest): Promise<User> {
    const tokens = await authApi.register(body)
    setSession(tokens)
    const profile = await authApi.me()
    setUser(profile)
    initialized.value = true
    return profile
  }

  async function restore(): Promise<void> {
    if (initialized.value) return
    if (!storage.getAccessToken()) {
      initialized.value = true
      return
    }
    try {
      accessToken.value = storage.getAccessToken()
      user.value = await authApi.me()
    } catch {
      clearSession()
    } finally {
      initialized.value = true
    }
  }

  async function logout(): Promise<void> {
    try {
      await authApi.logout()
    } catch {
      // 后端不可达时也必须完成本地登出。
    } finally {
      clearSession()
      initialized.value = true
    }
  }

  return {
    user,
    accessToken,
    initialized,
    isAuthenticated,
    isAdmin,
    login,
    register,
    restore,
    logout,
    setUser,
    clearSession,
  }
})
