      cause.code === 'validation_error'
    if (seq === requestSeq) {
      if (invalidCursor) {
        cursorStack.value = []
        ElMessage.warning('游标已失效，已回到第一页')
        await load()
        return
      }
      error.value = cause instanceof Error ? cause.message : '加载用户列表失败'
    }
  } finally {
    if (seq === requestSeq) loading.value = false
  }
}

